import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl } from "@babylonjs/lite";

export function attachFastOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext
): () => void {
  const originalAngularSensibility = camera.angularSensibility;
  const fastAngularSensibility = originalAngularSensibility / 2;
  const changed =
    Number.isFinite(originalAngularSensibility) &&
    originalAngularSensibility !== 0 &&
    Number.isFinite(fastAngularSensibility) &&
    fastAngularSensibility !== originalAngularSensibility;

  if (changed) {
    camera.angularSensibility = fastAngularSensibility;
  }

  let detach: (() => void) | undefined;
  try {
    detach = attachControl(camera, canvas, scene);
  } catch (error) {
    if (changed) {
      camera.angularSensibility = originalAngularSensibility;
    }
    throw error;
  }

  let disposed = false;
  return () => {
    if (disposed) {
      return;
    }
    disposed = true;
    detach?.();
    if (changed) {
      camera.angularSensibility = originalAngularSensibility;
    }
  };
}
```

I wrapped the library’s `attachControl` and temporarily halved `camera.angularSensibility` while attached, which doubles the pointer-drag rotation and its inertial glide while leaving wheel zoom and panning at their defaults. I wasn’t certain whether the package root exports `attachControl` exactly as the declarations imply, and I left the control options at the library default to keep the standard mouse/touch behavior.
